/* NU-019T: true guest 16-bit TCNT1 pre-load, WGM0 Timer1 overflow and W1C.
 * The CPU writes TCNT1 high followed by low with hardware TEMP semantics.
 * All events are generated by real peripheral countdown in simavr.
 * No host injection. Equal callback cycles are not silicon edge priority.
 */
#ifndef NU019T_START_LOW
#define NU019T_START_LOW 0xfc
#endif
#ifndef NU019T_NOP_COUNT
#define NU019T_NOP_COUNT 0
#endif
.text
.global start
start:
 rjmp init
.org 0x40
init:
 ldi r17,0x07
 out 0x16,r17
 ldi r16,0x55
 sts 0x0088,r16            /* OCR1AL nonzero, keep channel A out of the window */
 ldi r16,0xaa
 sts 0x008a,r16            /* OCR1BL nonzero, avoid channel B */
 ldi r16,0xff
 sts 0x0085,r16            /* TEMP high: TCNT1H */
 ldi r16,NU019T_START_LOW
 sts 0x0084,r16            /* commit TCNT1 high=0xff / low=0xf7..0xff */
 ldi r16,0x01
 sts 0x0081,r16            /* start Timer1 at CPU/1 in normal WGM0 */
 .rept NU019T_NOP_COUNT
 nop
 .endr
 in r19,0x16               /* flag before clear */
 ldi r17,0x01
 out 0x16,r17              /* W1C TOV1 */
 in r20,0x16               /* flag after clear */
 ldi r16,0
 sts 0x0081,r16            /* stop counter, retain TCNT1 */
 in r21,0x16
final_loop:
 nop
 rjmp final_loop
